def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    values = sorted(set(nums))
    result: list[str] = []
    i = 0
    n = len(values)

    while i < n:
        j = i
        while j + 1 < n and values[j + 1] == values[j] + 1:
            j += 1

        run_length = j - i + 1
        if run_length >= 3:
            result.append(f"{values[i]}..{values[j]}")
        else:
            for k in range(i, j + 1):
                result.append(str(values[k]))

        i = j + 1

    return ",".join(result)
